#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int sumaCyfr(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

int iloczynCzynnikow(int n) {
    int iloczyn = 1;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            iloczyn *= i;
            while (n % i == 0) n /= i;
        }
    }
    if (n > 1) iloczyn *= n;
    return iloczyn;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    string lista = "";
    cout << "a) Analiza:" << endl;
    while (plik >> n) {
        int sc = sumaCyfr(n);
        int ic = iloczynCzynnikow(n);
        cout << "   " << n << ": suma_cyfr=" << sc << ", iloczyn_czynnikow=" << ic << endl;
        if (sc == ic) {
            ile++;
            if (!lista.empty()) lista += " ";
            lista += to_string(n);
        }
    }
    cout << "b) Specjalne: " << lista << endl;
    cout << "c) Znaleziono: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Dwie funkcje pomocnicze: `sumaCyfr` wyodrebnia cyfry petla mod/div, `iloczynCzynnikow` znajduje rozne czynniki pierwsze faktoryzacja probna.

Weryfikacja:
- 2: sc=2, czynniki={2}, ic=2. 2==2 TAK
- 15=3*5: sc=1+5=6, ic=3*5=15. 6!=15 NIE
- 6=2*3: sc=6, ic=2*3=6. 6==6 TAK
- 10=2*5: sc=1+0=1, ic=2*5=10. 1!=10 NIE
- 3: sc=3, ic=3. 3==3 TAK
- 24=2^3*3: sc=2+4=6, ic=2*3=6. 6==6 TAK
- 8=2^3: sc=8, ic=2. 8!=2 NIE
- 5: sc=5, ic=5. 5==5 TAK
- 7: sc=7, ic=7. 7==7 TAK
- 12=2^2*3: sc=1+2=3, ic=2*3=6. 3!=6 NIE
- Specjalne: 2, 6, 3, 24, 5, 7 = 6
